import { fileURLToPath } from "node:url";
import { join, resolve } from "node:path";
import { cc0Text, erzeugePaket, svg, rect, circle, ellipse, line, path, poly, group, zufallFabrik, n } from "./tusche.mjs";

const PAKET_ID = "pk.zeitwelten", VERSION = "1.1.0", ZELLE = 64, URHEBER = "Chronicle contributors";
const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const zufall = zufallFabrik(PAKET_ID);
const C = { ink: "#263b43", edge: "#4e6267", steel: "#91a6ad", pale: "#d5dfdb", white: "#e9ede3", dark: "#3a4e55", teal: "#55a6a5", cyan: "#72dbe0", amber: "#dfac58", copper: "#b98766", wood: "#ba946c", green: "#879d79", fabric: "#718c96", red: "#b8614f", black: "#1c3039", glass: "#9ec9cc" };

/** Center anchors and whole-cell footprints are supplied by the existing package builder.
 * Margins include all contact shadows; no object quietly paints into its neighbour's cell. */
function drawing(name, title, units, draw, tiled = false, flat = tiled) {
  const w = units[0] * ZELLE, h = units[1] * ZELLE, id = `zw-${name}`;
  const gradient = (key, light, middle, dark) => `<linearGradient id="${id}-${key}" x1="0" y1="0" x2=".75" y2="1"><stop stop-color="${light}"/><stop offset=".5" stop-color="${middle}"/><stop offset="1" stop-color="${dark}"/></linearGradient>`;
  const defs = `<defs>${gradient("metal", "#c7d4d4", "#8da4ab", "#647e89")}${gradient("ceramic", "#f2f1e5", "#d7e0db", "#a4b7b4")}${gradient("wood", "#d1af80", "#b68d60", "#8d6848")}${gradient("fabric", "#a4b6b6", "#728e99", "#4e6b79")}${gradient("copper", "#d7b08b", "#af7b57", "#815640")}${gradient("glass", "#b7e1df", "#6aa7b5", "#3f737f")}<filter id="${id}-shadow" x="-10%" y="-10%" width="120%" height="125%"><feDropShadow dx="0" dy="1.6" stdDeviation="1.2" flood-color="#13262c" flood-opacity=".32"/></filter><clipPath id="${id}-bounds">${rect(0, 0, w, h)}</clipPath></defs>`;
  const p = Object.fromEntries(["metal", "ceramic", "wood", "fabric", "copper", "glass"].map(key => [key, `url(#${id}-${key})`]));
  return svg(title, w, h, defs + group({ "clip-path": `url(#${id}-bounds)` }, group(flat ? {} : { filter: `url(#${id}-shadow)` }, draw({ w, h, p, r: zufall(name) }))));
}
const R = (x, y, w, h, fill = C.steel, radius = 3, extra = {}) => rect(x, y, w, h, { rx: radius, fill, stroke: C.ink, "stroke-width": 1.15, ...extra });
const F = (x, y, w, h, fill, radius = 0, extra = {}) => rect(x, y, w, h, { rx: radius, fill, ...extra });
const L = (x, y, x2, y2, color = C.edge, width = 1, extra = {}) => line(x, y, x2, y2, { stroke: color, "stroke-width": width, "stroke-linecap": "round", ...extra });
const O = (x, y, radius, fill, extra = {}) => circle(x, y, radius, { fill, stroke: C.ink, "stroke-width": 1, ...extra });
const P = (d, fill = "none", stroke = C.ink, width = 1.2, extra = {}) => path(d, { fill, stroke, "stroke-width": width, "stroke-linejoin": "round", "stroke-linecap": "round", ...extra });
const slab = (x, y, w, h, fill, radius = 3) => R(x, y, w, h, fill, radius) + L(x + 3, y + 2, x + w - 3, y + 2, "#fff", .9, { opacity: .55 });
const cross = (x, y, size = 12, color = C.teal) => F(x - size / 6, y - size / 2, size / 3, size, color, 1) + F(x - size / 2, y - size / 6, size, size / 3, color, 1);
const bolts = (x, y, w, h) => [[x, y], [x + w, y], [x, y + h], [x + w, y + h]].map(([cx, cy]) => O(cx, cy, 1.3, C.pale) + L(cx - .6, cy, cx + .6, cy, C.edge, .6)).join("");
const ribs = (x, y, w, h, count = 6) => F(x, y, w, h, C.dark, 1) + Array.from({ length: count }, (_, i) => L(x + 2, y + (i + .5) * h / count, x + w - 2, y + (i + .5) * h / count, C.steel, 1.1)).join("");
const screen = (x, y, w, h) => R(x, y, w, h, C.black, 2) + F(x + 2, y + 2, w - 4, h - 4, "#234b59", 1) + P(`M${x + 4} ${y + h * .65}h${n(w * .15)}l${n(w * .12)} ${n(-h * .28)}l${n(w * .12)} ${n(h * .4)}l${n(w * .14)} ${n(-h * .24)}h${n(w * .17)}`, "none", C.cyan, 1) + L(x + 4, y + 4, x + w * .55, y + 4, "#b0e9df", .6);
const chair = (cx, cy, fill, angle = 0) => group({ transform: `rotate(${angle} ${cx} ${cy})` }, R(cx - 9, cy - 7, 18, 16, fill, 5), slab(cx - 11, cy - 11, 22, 6, fill, 3), R(cx - 12, cy - 3, 3, 11, C.dark, 1), R(cx + 9, cy - 3, 3, 11, C.dark, 1));
const plant = (cx, cy, radius = 12) => O(cx, cy, radius * .7, C.copper) + Array.from({ length: 7 }, (_, i) => ellipse(cx, cy - radius * .42, radius * .28, radius * .65, { fill: i % 2 ? "#718f63" : "#a0b186", stroke: "#435e49", "stroke-width": .7, transform: `rotate(${i * 360 / 7} ${cx} ${cy})` })).join("") + O(cx, cy, 2.5, "#c9d2a8");
const hazard = (x, y, w, h) => F(x, y, w, h, C.amber, 1) + Array.from({ length: Math.floor(w / 9) }, (_, i) => poly([[x + i * 9 + 2, y + h], [x + i * 9 + 6, y], [x + i * 9 + 9, y], [x + i * 9 + 5, y + h]], { fill: C.dark })).join("");
const arrow = (x, y, length, color = C.white) => P(`M${x} ${y + length}V${y}m-4 5l4 -5l4 5`, "none", color, 2);
const keys = (x, y, cols = 7, rows = 3) => R(x, y, cols * 4 + 3, rows * 4 + 2, C.pale, 1) + Array.from({ length: rows * cols }, (_, i) => F(x + 2 + i % cols * 4, y + 2 + Math.floor(i / cols) * 4, 2.5, 2, C.edge, .4)).join("");
const books = (x, y, count = 7, vertical = false) => Array.from({ length: count }, (_, i) => {
  const colors = [C.teal, C.amber, C.red, C.pale, C.fabric];
  return vertical ? R(x, y + i * 6, 16 + i % 3 * 2, 5, colors[i % colors.length], .5) : R(x + i * 6, y, 5, 16 + i % 3 * 2, colors[i % colors.length], .5);
}).join("");
const bed = (x, y, w, h, p) => slab(x, y, w, h, p.wood, 3) + R(x + 3, y + 4, w - 6, h - 8, p.ceramic, 5) + R(x + 6, y + 8, w - 12, 15, C.white, 4) + R(x + 4, y + 29, w - 8, h - 36, p.fabric, 4) + L(x + 5, y + 36, x + w - 5, y + 36, C.pale, 2) + P(`M${x + 10} ${y + 42}q5 7 0 14m${w - 22} 7q-5 8 0 13`, "none", "#536f7c", .8);

const KATALOG = [];
/** `flat` drops the contact shadow without making the piece a floor tile: rugs lie on the floor. */
function add(name, title, art, units, tags, draw, tiled = false, flat = tiled) {
  KATALOG.push({ name, art, einheiten: units, schlagworte: tags.split(" "), kachelbar: tiled, zeichne: () => drawing(name, title, units, draw, tiled, flat) });
}

// 01–12: Böden. Materialien, keine Farbkopien; alle Randmuster schließen in einem 4×4-Feld.
add("boden_beton", "Geglätteter Beton mit Dehnfugen", "boden", [1, 1], "beton trocken halle keller industrie", ({ r }) => F(0, 0, 64, 64, "#a1aaa7") + Array.from({ length: 75 }, () => circle(r.zahl(1, 63), r.zahl(1, 63), r.zahl(.15, .6), { fill: r.waehle(["#778886", "#c5cebf"]), opacity: .45 })).join("") + R(.6, .6, 62.8, 62.8, "none", 0, { stroke: "#72827e", "stroke-width": 1.2 }) + L(2, 2, 62, 2, "#cfdbcd", .7), true);
add("boden_parkett", "Geflochtener Eichenparkettboden", "boden", [1, 1], "holz wohnraum gehoben trocken gegenwart", () => F(0, 0, 64, 64, "#755a40") + Array.from({ length: 16 }, (_, i) => {
  const x = i % 4 * 16, y = Math.floor(i / 4) * 16, vertical = (i % 4 + Math.floor(i / 4)) % 2;
  return F(x + .5, y + .5, 15, 15, ["#b39876", "#c2a57d", "#a98b65"][i % 3]) + [4, 8, 12].map(t => vertical ? L(x + t, y + 1, x + t, y + 15, "#826443", .65) : L(x + 1, y + t, x + 15, y + t, "#826443", .65)).join("");
}).join(""), true);
add("boden_keramik", "Keramikfliesen mit Kreuzfugen", "boden", [1, 1], "fliese fliesen trocken wohnraum halle medizin", () => F(0, 0, 64, 64, "#8d9d99") + [[1, 1], [33, 1], [1, 33], [33, 33]].map(([x, y], i) => F(x, y, 30, 30, i % 3 ? "#dce2d5" : "#c9d6cc", .8) + L(x + 1, y + 1, x + 28, y + 1, "#f6f5e8", 1)).join(""), true);
add("boden_teppich", "Gewebter Akustikteppich", "boden", [1, 1], "teppich wohnraum trocken buero", () => F(0, 0, 64, 64, "#6b8183") + Array.from({ length: 256 }, (_, i) => L(i % 16 * 4, Math.floor(i / 16) * 4, i % 16 * 4 + 2, Math.floor(i / 16) * 4 + 2, i % 3 ? "#8d9c97" : "#526b74", .65)).join(""), true);
add("boden_linoleum", "Steriles Linoleum mit mineralischen Einlagen", "boden", [1, 1], "steril medizin labor fliesen trocken", ({ r }) => F(0, 0, 64, 64, "#c7dad0") + Array.from({ length: 65 }, () => ellipse(r.zahl(1, 63), r.zahl(1, 63), r.zahl(.3, 1.6), r.zahl(.2, .7), { fill: r.waehle(["#94b5ac", "#eef0d9", "#a5c6ba"]), opacity: .75 })).join(""), true);
add("boden_gitter", "Industrieller Stahlrost", "boden", [1, 1], "metall industrie technik keller", ({ p }) => F(0, 0, 64, 64, C.black) + Array.from({ length: 8 }, (_, i) => F(i * 8, 0, 3, 64, p.metal) + F(0, i * 8, 64, 2, "#759398")).join("") + bolts(4, 4, 56, 56), true);
add("boden_asphalt", "Asphaltbelag mit Gesteinskörnung", "boden", [1, 1], "asphalt strasse trocken gegenwart", ({ r }) => F(0, 0, 64, 64, "#586265") + Array.from({ length: 130 }, () => circle(r.zahl(.5, 63.5), r.zahl(.5, 63.5), r.zahl(.2, .7), { fill: r.waehle(["#a7aaa0", "#323f45", "#78817c"]), opacity: .8 })).join(""), true);
add("boden_pflaster", "Versetztes Stadtpflaster", "boden", [1, 1], "stein trocken halle gehoben strasse", () => F(0, 0, 64, 64, "#566765") + Array.from({ length: 5 }, (_, row) => Array.from({ length: 5 }, (_, col) => F(col * 16 - (row % 2 ? 8 : 0) + .7, row * 16 + .7, 14.6, 14.6, ["#b2b6a2", "#a2ae9d", "#c0c4af"][(col + row) % 3], 2)).join("")).join(""), true);
add("boden_metalldeck", "Raumstationsdeck mit Wartungsklappen", "boden", [1, 1], "metall technik halle trocken scifi", ({ p }) => F(0, 0, 64, 64, C.dark) + R(2, 2, 60, 60, p.metal, 3) + R(10, 9, 44, 46, "#7c949d", 3) + L(10, 20, 54, 20, "#bed0cf", 1) + ribs(22, 44, 20, 6, 3) + bolts(6, 6, 52, 52), true);
