add("boden_erde", "Verdichtete Erde mit Kies", "boden", [1, 1], "erde trocken hof", ({ r }) => F(0, 0, 64, 64, "#a09677") + Array.from({ length: 60 }, () => ellipse(r.zahl(1, 63), r.zahl(1, 63), r.zahl(.35, 2.2), r.zahl(.3, 1.2), { fill: r.waehle(["#c4b99a", "#7d8068", "#8d8067"]), opacity: .7 })).join("") + P("M5 22q8 -3 11 0m28 26q8 -3 13 0M18 55l3 2", "none", "#7d755c", .6), true);
add("boden_sicherheitszone", "Bodenmarkierung für Maschinenabstand", "boden", [1, 1], "industrie beton sicherheit", () => F(0, 0, 64, 64, "#849594") + hazard(0, 0, 64, 8) + hazard(0, 56, 64, 8) + R(9, 13, 46, 38, "none", 1, { stroke: "#c4cbc0", "stroke-dasharray": "4 4" }) + bolts(15, 20, 34, 24), true);

