// 89–100: Straßenniveau und Dachlandschaft; Fahrzeuge besitzen maßstäbliche Grundflächen.
function roadVehicle(kind, { p, w, h }) {
  const long = kind !== "auto", x = 18, bw = w - 36;
  let out = [12, w - 22].flatMap(wx => [h * .24, h * .73].map(wy => R(wx, wy, 10, long ? 31 : 25, C.black, 3))).join("");
  const fill = kind === "feuerwehr" ? p.copper : kind === "ambulanz" ? p.ceramic : kind === "bus" ? p.metal : p.fabric;
  out += slab(x, 8, bw, h - 16, fill, kind === "auto" ? 22 : 12);
  out += P(`M${x + 8} 37Q${w / 2} 27 ${w - x - 8} 37L${w - x - 5} 60Q${w / 2} 51 ${x + 5} 60Z`, p.glass);
  out += P(`M${x + 7} ${h - 46}Q${w / 2} ${h - 34} ${w - x - 7} ${h - 46}L${w - x - 8} ${h - 24}H${x + 8}Z`, C.dark);
  out += [x + 8, w - x - 17].map(lx => R(lx, 15, 9, 7, C.white, 2) + R(lx, h - 19, 9, 5, C.red, 1)).join("");
  if (kind === "auto") out += R(x + 8, 65, bw - 16, h - 117, fill, 10) + L(x + 8, 73, x + 8, h - 58, C.pale, 1) + L(w - x - 8, 73, w - x - 8, h - 58, C.dark, 1.2);
  if (kind === "bus") out += R(x + 7, 70, bw - 14, h - 126, fill, 3) + [83, 135, 187].map(y => ribs(x + 19, y, bw - 38, 30, 6)).join("") + L(x + 3, 70, x + 3, h - 58, C.teal, 3);
  if (kind === "ambulanz") out += R(x + 7, 72, bw - 14, h - 128, C.white, 5) + cross(w / 2, h / 2 + 10, 38, C.teal) + R(x + 12, 61, bw - 24, 8, C.teal, 2) + F(x + 18, 62, 17, 6, C.cyan, 1) + F(w - x - 35, 62, 17, 6, C.cyan, 1);
  if (kind === "feuerwehr") out += R(x + 7, 71, bw - 14, h - 129, C.dark, 4) + R(x + 16, 79, bw - 32, h - 145, p.metal, 2) + [x + 20, w - x - 20].map(lx => L(lx, 86, lx, h - 72, C.pale, 3)).join("") + Array.from({ length: 11 }, (_, i) => L(x + 20, 90 + i * 11, w - x - 20, 90 + i * 11, C.pale, 2)).join("") + O(w / 2, h - 48, 15, C.dark) + O(w / 2, h - 48, 10, C.copper) + R(x + 12, 61, bw - 24, 7, C.cyan, 2);
  return out;
}
